import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 평가 일시는 등록·수정 시각(now())으로 채운다
// 가정: 교육 종료 이후 = 교육 종료일이 오늘보다 이전
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || (typeof v === 'string' && v.trim() === '');
}

function toId(v: unknown, label: string): number {
  const n = typeof v === 'number' ? v : Number(v);
  if (isBlank(v) || !Number.isInteger(n)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return n;
}

function toScore(v: unknown): number | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  const n = typeof v === 'number' ? v : Number(v);
  if (typeof v === 'boolean' || !Number.isFinite(n) || n < 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '점수는 0 이상의 숫자여야 합니다.');
  }
  return n;
}

function toCompleted(v: unknown): boolean | null {
  if (v === undefined || v === null) {
    return null;
  }
  if (typeof v !== 'boolean') {
    throw new ApiError(400, 'VALIDATION_FAILED', '수료 여부는 true 또는 false여야 합니다.');
  }
  return v;
}

@Controller('api/v1')
export class FnSfr01504Controller {
  @Get('/education-evaluations')
  async listEducationEvaluations(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '인사 담당자');
    const q = checks.queryOf(req.query);
    const educationSessionId = toId(q['educationSessionId'], '교육 차수');
    const page = isBlank(q['page']) ? 0 : Number(q['page']);
    const size = isBlank(q['size']) ? DEFAULT_SIZE : Number(q['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 정보가 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    return transaction(async (db) => {
      const totalRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM education_evaluation ev JOIN education_attendee at ON at.education_attendee_id = ev.education_attendee_id WHERE at.education_session_id = :sessionId',
        { sessionId: educationSessionId },
      );
      const items = await db.query(
        'SELECT ev.education_evaluation_id AS "educationEvaluationId", ev.education_attendee_id AS "educationAttendeeId", em.name AS "employeeName", ev.evaluation_item AS "evaluationItem", ev.score AS "score", ev.completed AS "completed", ev.evaluated_at AS "evaluatedAt" FROM education_evaluation ev JOIN education_attendee at ON at.education_attendee_id = ev.education_attendee_id JOIN employee em ON em.employee_id = at.employee_id WHERE at.education_session_id = :sessionId ORDER BY ev.education_evaluation_id LIMIT :limit OFFSET :offset',
        { sessionId: educationSessionId, limit, offset: page * limit },
      );
      return { items, page, size: limit, total: Number(totalRows[0]['total']) };
    });
  }

  @Post('/education-evaluations')
  @HttpCode(200)
  async createEducationEvaluation(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const data = checks.inputOf(req.body);
    const attendeeId = toId(data['educationAttendeeId'], '교육대상자');
    const item = data['evaluationItem'];
    if (typeof item !== 'string' || item.trim() === '') {
      throw new ApiError(422, 'EVALUATION_ITEM_REQUIRED', '평가 항목을 입력해 주세요.');
    }
    if (item.length > 200) {
      throw new ApiError(400, 'VALIDATION_FAILED', '평가 항목은 200자 이내로 입력해 주세요.');
    }
    const score = toScore(data['score']);
    const completed = toCompleted(data['completed']);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT (s.end_date < CURRENT_DATE) AS "ended" FROM education_attendee a JOIN education_session s ON s.education_session_id = a.education_session_id WHERE a.education_attendee_id = :attendeeId',
        { attendeeId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'EDUCATION_ATTENDEE_NOT_FOUND', '교육대상자로 등록되지 않은 임직원입니다.');
      }
      if (found[0]['ended'] !== true) {
        throw new ApiError(422, 'EDUCATION_NOT_ENDED', '교육이 종료된 뒤에 평가를 등록할 수 있습니다.');
      }
      const dup = await db.query(
        'SELECT 1 AS "x" FROM education_evaluation WHERE education_attendee_id = :attendeeId AND evaluation_item = :item',
        { attendeeId, item },
      );
      if (dup.length > 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '이미 등록된 평가 항목입니다.');
      }
      const rows = await db.query(
        'INSERT INTO education_evaluation (education_attendee_id, evaluation_item, score, completed, evaluated_at, created_at, updated_at) VALUES (:attendeeId, :item, CAST(:score AS numeric), CAST(:completed AS boolean), now(), now(), now()) RETURNING education_evaluation_id AS "educationEvaluationId", education_attendee_id AS "educationAttendeeId", evaluation_item AS "evaluationItem", score AS "score", completed AS "completed"',
        { attendeeId, item, score, completed },
      );
      return rows[0];
    });
  }

  @Patch('/education-evaluations/:educationEvaluationId')
  async updateEducationEvaluation(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const evaluationId = toId(req.params['educationEvaluationId'], '교육평가');
    const data = checks.inputOf(req.body);
    let item: string | null = null;
    if (data['evaluationItem'] !== undefined) {
      const v = data['evaluationItem'];
      if (typeof v !== 'string' || v.trim() === '') {
        throw new ApiError(422, 'EVALUATION_ITEM_REQUIRED', '평가 항목을 입력해 주세요.');
      }
      if (v.length > 200) {
        throw new ApiError(400, 'VALIDATION_FAILED', '평가 항목은 200자 이내로 입력해 주세요.');
      }
      item = v;
    }
    const score = toScore(data['score']);
    const completed = toCompleted(data['completed']);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT education_attendee_id AS "attendeeId" FROM education_evaluation WHERE education_evaluation_id = :evaluationId',
        { evaluationId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'EDUCATION_EVALUATION_NOT_FOUND', '평가를 찾을 수 없습니다.');
      }
      if (item !== null) {
        const dup = await db.query(
          'SELECT 1 AS "x" FROM education_evaluation WHERE education_attendee_id = :attendeeId AND evaluation_item = :item AND education_evaluation_id <> :evaluationId',
          { attendeeId: found[0]['attendeeId'], item, evaluationId },
        );
        if (dup.length > 0) {
          throw new ApiError(400, 'VALIDATION_FAILED', '이미 등록된 평가 항목입니다.');
        }
      }
      const rows = await db.query(
        'UPDATE education_evaluation SET evaluation_item = COALESCE(CAST(:item AS varchar), evaluation_item), score = COALESCE(CAST(:score AS numeric), score), completed = COALESCE(CAST(:completed AS boolean), completed), evaluated_at = now(), updated_at = now() WHERE education_evaluation_id = :evaluationId RETURNING education_evaluation_id AS "educationEvaluationId", evaluation_item AS "evaluationItem", score AS "score", completed AS "completed"',
        { item, score, completed, evaluationId },
      );
      return rows[0];
    });
  }
}

response.page:
import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  NumberInput,
  Select,
  LookupSelect,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const COMPLETED_OPTIONS: [string, string][] = [
  ['true', '수료'],
  ['false', '미수료'],
];

export default function FnSfr01504Page({ role, notify }: PageProps) {
  const canEdit = role === '인사 담당자';
  const [draftSession, setDraftSession] = useState<number | string>('');
  const [sessionId, setSessionId] = useState<number | string>('');
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);

  const [attendeeId, setAttendeeId] = useState<number | string>('');
  const [item, setItem] = useState('');
  const [score, setScore] = useState<number | string>('');
  const [completed, setCompleted] = useState('');

  const list = useData<Page>(async () => {
    if (sessionId === '') {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', '/education-evaluations', role, undefined, {
      educationSessionId: sessionId,
      page,
      size: SIZE,
    });
  }, [sessionId, page, role]);

  function search() {
    setPage(0);
    setSessionId(draftSession);
  }

  function reset() {
    setDraftSession('');
    setSessionId('');
    setPage(0);
  }

  function openCreate() {
    setAttendeeId('');
    setItem('');
    setScore('');
    setCompleted('');
    setCreating(true);
  }

  function openEdit(row: Row) {
    setItem(String(row['evaluationItem'] ?? ''));
    setScore(row['score'] === null || row['score'] === undefined ? '' : (row['score'] as number));
    setCompleted(row['completed'] === true ? 'true' : row['completed'] === false ? 'false' : '');
    setEditing(row);
  }

  async function submitCreate() {
    if (attendeeId === '') {
      throw new Error('교육대상자를 선택해 주세요.');
    }
    if (item.trim() === '') {
      throw new Error('평가 항목을 입력해 주세요.');
    }
    const body: Row = { educationAttendeeId: attendeeId, evaluationItem: item };
    if (score !== '') {
      body.score = score;
    }
    if (completed !== '') {
      body.completed = completed === 'true';
    }
    await call('POST', '/education-evaluations', role, body);
    notify('교육평가를 등록했습니다.');
    setCreating(false);
    list.reload();
  }

  async function submitEdit() {
    if (!editing) {
      return;
    }
    if (item.trim() === '') {
      throw new Error('평가 항목을 입력해 주세요.');
    }
    const body: Row = { evaluationItem: item };
    if (score !== '') {
      body.score = score;
    }
    if (completed !== '') {
      body.completed = completed === 'true';
    }
    await call('PATCH', '/education-evaluations/' + String(editing['educationEvaluationId']), role, body);
    notify('교육평가를 수정했습니다.');
    setEditing(null);
    list.reload();
  }

  const data = list.data;

  return (
    <div>
      <h1>교육평가 관리</h1>
      <Filters onSearch={search} onReset={reset}>
        <Field label='교육 차수' required>
          <LookupSelect
            table='education_session'
            role={role}
            value={draftSession}
            onChange={setDraftSession}
            placeholder='교육 차수 선택'
          />
        </Field>
      </Filters>
      <Band total={data ? data.total : 0}>
        {canEdit && (
          <button onClick={openCreate}>평가 등록</button>
        )}
      </Band>
      {list.error !== '' && <p>{list.error}</p>}
      <DataTable
        rows={data ? data.items : []}
        onRowClick={canEdit ? openEdit : undefined}
        empty={sessionId === '' ? '교육 차수를 선택하고 조회해 주세요.' : '아직 등록한 평가가 없습니다. 평가 등록 버튼으로 시작해 주세요.'}
        columns={[
          { key: 'employeeName', label: '임직원명' },
          { key: 'evaluationItem', label: '평가 항목' },
          { key: 'score', label: '점수', render: (r) => <Num value={r['score']} /> },
          {
            key: 'completed',
            label: '수료 여부',
            render: (r) => <Badge value={r['completed'] === true ? '수료' : r['completed'] === false ? '미수료' : ''} />,
          },
          { key: 'evaluatedAt', label: '평가 일시', render: (r) => <DateText value={r['evaluatedAt']} time /> },
        ]}
      />
      <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      {creating && (
        <Drawer title='교육평가 등록' onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit='등록'>
            <Field label='교육대상자 ID' required>
              <LookupSelect
                table='education_attendee'
                role={role}
                value={attendeeId}
                onChange={setAttendeeId}
                placeholder='교육대상자 선택'
              />
            </Field>
            <Field label='평가 항목' required>
              <TextInput value={item} onChange={setItem} />
            </Field>
            <Field label='점수'>
              <NumberInput value={score} onChange={setScore} />
            </Field>
            <Field label='수료 여부'>
              <Select value={completed} onChange={setCompleted} options={COMPLETED_OPTIONS} />
            </Field>
          </Form>
        </Drawer>
      )}
      {editing && (
        <Drawer title='교육평가 수정' onClose={() => setEditing(null)}>
          <Form onSubmit={submitEdit} submit='저장'>
            <Field label='평가 항목' required>
              <TextInput value={item} onChange={setItem} />
            </Field>
            <Field label='점수'>
              <NumberInput value={score} onChange={setScore} />
            </Field>
            <Field label='수료 여부'>
              <Select value={completed} onChange={setCompleted} options={COMPLETED_OPTIONS} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
